package dev.voyage.workbench;
import org.json.*;import java.net.*;import java.io.*;import android.util.Base64;
final class NativeImages {
 static URL publicUrl(String value)throws Exception{URL u=new URL(value);if(!"https".equals(u.getProtocol())||u.getUserInfo()!=null||(u.getPort()!=-1&&u.getPort()!=443))throw new Exception("Image transport requires public HTTPS");for(InetAddress a:InetAddress.getAllByName(u.getHost()))if(a.isAnyLocalAddress()||a.isLoopbackAddress()||a.isLinkLocalAddress()||a.isSiteLocalAddress()||a.isMulticastAddress()||((a.getAddress()[0]&0xfe)==0xfc&&a.getAddress().length==16))throw new Exception("Image transport requires public address");return u;}
 static JSONObject generate(Host host,String prompt,String reference,JSONObject snapshot)throws Exception{JSONObject route=(JSONObject)host.store.core.doc("imageRoute",host.settings(),snapshot==null?JSONObject.NULL:snapshot);if("codex".equals(route.getString("protocol")))return CodexMedia.generate(host,route,prompt,reference);String key=host.secrets.get("provider-"+route.getString("id"));JSONObject headers=new JSONObject().put("Content-Type","application/json");if(!key.isEmpty())headers.put("Authorization","Bearer "+key);JSONObject body=new JSONObject().put("model",route.getString("model")).put("prompt",prompt).put("n",1);if(!route.getString("model").startsWith("gpt-image"))body.put("response_format","b64_json");String endpoint="/images/generations";byte[] payload=body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(!reference.isEmpty()){if(!reference.matches("^data:image/(png|jpeg|webp);base64,.+"))throw new Exception("Invalid reference image");endpoint="/images/edits";if("api.x.ai".equals(new URL(route.getString("baseUrl")).getHost())){body.put("image",new JSONObject().put("url",reference).put("type","image_url"));payload=body.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);}else{String boundary="Voyage"+java.util.UUID.randomUUID().toString();headers.put("Content-Type","multipart/form-data; boundary="+boundary);ByteArrayOutputStream form=new ByteArrayOutputStream();java.util.Iterator<String> names=body.keys();while(names.hasNext()){String field=names.next();form.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+field+"\"\r\n\r\n"+body.get(field)+"\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));}String mime=reference.substring(5,reference.indexOf(';'));form.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"image\"; filename=\"reference."+mime.substring(6)+"\"\r\nContent-Type: "+mime+"\r\n\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));form.write(Base64.decode(reference.split(",",2)[1],Base64.DEFAULT));form.write(("\r\n--"+boundary+"--\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8));payload=form.toByteArray();}}JSONObject data=Providers.httpBytes(route.getString("baseUrl")+endpoint,headers,payload).getJSONArray("data").getJSONObject(0);String image;if(data.has("b64_json"))image="data:image/png;base64,"+data.getString("b64_json");else{HttpURLConnection c=(HttpURLConnection)publicUrl(data.getString("url")).openConnection();try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(60000);if(c.getResponseCode()!=200)throw new Exception("Generated image download failed");String mime=c.getContentType().split(";")[0];if(!mime.matches("image/(png|jpeg|webp)"))throw new Exception("Unexpected image type");image="data:"+mime+";base64,"+Base64.encodeToString(read(c.getInputStream(),24*1024*1024),Base64.NO_WRAP);}finally{c.disconnect();}}return new JSONObject().put("dataUrl",image).put("route",route);}
 static byte[] read(InputStream in,int max)throws Exception{try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=stream.read(b))!=-1){if(out.size()+n>max)throw new Exception("Image too large");out.write(b,0,n);}return out.toByteArray();}}
 static JSONObject upload(JSONObject p)throws Exception{String mime=p.getString("mime");if(!mime.matches("(image/(png|jpeg|webp)|audio/(mpeg|wav|ogg|mp4))"))throw new Exception("Unsupported media type");int limit=(mime.startsWith("audio/")?25:5)*1024*1024;String encoded=p.getString("base64");if(encoded.length()>4*((limit+2)/3))throw new Exception("Media exceeds upload size limit");byte[] data=Base64.decode(encoded,Base64.DEFAULT);if(data.length>limit)throw new Exception("Media exceeds upload size limit");HttpURLConnection c=(HttpURLConnection)publicUrl(p.getString("url")).openConnection();try{c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setRequestMethod("PUT");c.setRequestProperty("Content-Type",mime);c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(data);}int status=c.getResponseCode();if(status<200||status>=300)throw new Exception("Signed upload HTTP "+status);return new JSONObject().put("ok",true);}finally{c.disconnect();}}
}
